it("compares each sheet's set of priorities for every selector and property both sheets declare", () => {
	const release = new SheetReader(
		readBootstrapCascade(),
	)
	const cascade = new SheetReader(readBuiltCascade())
	const written = new Map<string, ReadonlySet<boolean>>()
	for (const declaration of release.declarations) {
		const pair = `${declaration.selector} { ${declaration.property} }`
		written.set(pair, new Set([...(written.get(pair) ?? []), declaration.important]))
	}
	const shipped = new Map<string, ReadonlySet<boolean>>()
	for (const declaration of cascade.declarations) {
		const pair = `${declaration.selector} { ${declaration.property} }`
		shipped.set(pair, new Set([...(shipped.get(pair) ?? []), declaration.important]))
	}
	const mismatches: string[] = []
	let compared = 0
	for (const [pair, priorities] of written) {
		const carried = shipped.get(pair)
		if (carried === undefined) continue
		compared += 1
		if (priorities.size !== carried.size || [...priorities].some((entry) => !carried.has(entry)))
			mismatches.push(
				`${pair}: release ${[...priorities].map((entry) => (entry ? 'important' : 'normal')).join(' and ')}, cascade ${[...carried].map((entry) => (entry ? 'important' : 'normal')).join(' and ')}`,
			)
	}
	expect(compared).toBeGreaterThan(0)
	expect(mismatches).toEqual([])
})
